#include <iostream>
#include <vector>
using namespace std;

const long long MOD = 1000000007;

long long power(long long b, long long e) {
    long long r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    int n, k;
    cin >> n >> k;
    int m = n - k;
    vector<long long> d(m + 2, 0), fact(n + 1, 1);
    d[0] = 1;
    for (int i = 2; i <= m; i++) d[i] = (long long)(i - 1) * ((d[i - 1] + d[i - 2]) % MOD) % MOD;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    long long c = fact[n] * power(fact[k] * fact[n - k] % MOD, MOD - 2) % MOD;
    cout << c * d[m] % MOD << '\n';
    return 0;
}

